sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    console.log(event.payload);
    if (event.payload.id == 'card_base_container_1')
        api.setState('selectedTab', '0');
    else if (event.payload.id == 'card_base_container_2')
        api.setState('selectedTab', '1');
    else if (event.payload.id == 'card_base_container_3')
        api.setState('selectedTab', '2');
}
